-- Schema snapshot of the original application, used only with an in-memory test DB.
CREATE TABLE employees (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
emp_no varchar(255) NOT NULL,
name varchar(255) NOT NULL,
department_code varchar(50) default 'DEPT_RND',
department varchar(255) NOT NULL,
position_code varchar(50) default 'POS_STAFF',
position varchar(255) NOT NULL,
email varchar(255) NOT NULL,
phone varchar(255) NOT NULL,
hire_date varchar(255) NOT NULL,
status varchar(255) NOT NULL,
leave_remaining double precision NOT NULL,
leave_total double precision NOT NULL,
skills varchar(255) NOT NULL,
avatar_color varchar(255) NOT NULL,
role varchar(50) default '일반직원',
password varchar(100) default '1234'
);
CREATE TABLE projects (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
code varchar(255) NOT NULL,
name varchar(255) NOT NULL,
department varchar(255) NOT NULL,
pm_name varchar(255) NOT NULL,
start_date varchar(255) NOT NULL,
end_date varchar(255) NOT NULL,
status varchar(255) NOT NULL,
progress integer NOT NULL,
budget integer NOT NULL,
share_rate numeric(5,2) default 100.0,
our_budget integer default 0,
is_consortium boolean default false,
consortium_partners varchar(500) default '',
members varchar(255) NOT NULL,
priority varchar(255) NOT NULL,
description varchar(1000) NOT NULL
);
CREATE TABLE equipments (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
asset_no varchar(255) NOT NULL,
category varchar(255) NOT NULL,
model_name varchar(255) NOT NULL,
serial_no varchar(255) NOT NULL,
status varchar(255) NOT NULL,
emp_id bigint,
emp_no varchar(50),
assigned_to varchar(255) NOT NULL,
department varchar(255) NOT NULL,
purchase_date varchar(255) NOT NULL,
price integer NOT NULL,
notes varchar(1000) NOT NULL
);
CREATE TABLE business_deals (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
title varchar(255) NOT NULL,
client_name varchar(255) NOT NULL,
owner_name varchar(255) NOT NULL,
stage varchar(255) NOT NULL,
amount integer NOT NULL,
probability integer NOT NULL,
close_date varchar(255) NOT NULL,
deal_type varchar(255) NOT NULL,
notes varchar(1000) NOT NULL
);
CREATE TABLE evaluations (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
emp_no varchar(255) NOT NULL,
emp_name varchar(255) NOT NULL,
department_code varchar(50) default 'DEPT_RND',
department varchar(255) NOT NULL,
position_code varchar(50) default 'POS_STAFF',
position varchar(255) NOT NULL,
period varchar(255) NOT NULL,
kpi_score integer NOT NULL,
competency_score integer NOT NULL,
peer_score integer NOT NULL,
total_score double precision NOT NULL,
grade varchar(255) NOT NULL,
reviewer varchar(255) NOT NULL,
status varchar(255) NOT NULL,
feedback varchar(1000) NOT NULL
);
CREATE TABLE approvals (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
doc_no varchar(255) NOT NULL,
category varchar(255) NOT NULL,
title varchar(255) NOT NULL,
requester varchar(255) NOT NULL,
requester_position varchar(50) default '과장',
department varchar(255) NOT NULL,
created_at varchar(255) NOT NULL,
status varchar(255) NOT NULL,
amount integer NOT NULL,
project_name varchar(255) default '',
vendor varchar(255) default '',
payment_method varchar(100) default '세금계산서(계좌이체)',
purpose text default '',
items_json text default '[]',
reviewer_comment varchar(500) default '',
approved_by varchar(100) default ''
);
CREATE TABLE common_codes (
id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
group_code varchar(50) NOT NULL,
group_name varchar(100) NOT NULL,
code varchar(50) NOT NULL,
code_name varchar(100) NOT NULL,
sort_order integer NOT NULL,
is_active boolean NOT NULL,
extra_value varchar(200)
);